[metadata] {"type": "create", "filePath": "/app/src/main/java/com/example/views/MessageStore.java", "content": "package com.example.views;

import java.io.Serializable;
import java.util.ArrayList;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * The messages sent so far, newest first.
 * <p>
 * Kept in the {@link VaadinSession}, so the list outlives a single visit to the
 * contact view: navigating away and back shows everything that has been sent.
 */
public class MessageStore implements Serializable {

    private final List<ContactMessage> messages = new ArrayList<>();

    /**
     * The store of the current session, created on first use.
     */
    public static MessageStore current() {
        VaadinSession session = VaadinSession.getCurrent();
        if (session == null) {
            // No session (e.g. a background thread): an empty, throw-away store
            // is better than a NullPointerException.
            return new MessageStore();
        }
        MessageStore store = session.getAttribute(MessageStore.class);
        if (store == null) {
            store = new MessageStore();
            session.setAttribute(MessageStore.class, store);
        }
        return store;
    }

    /**
     * The messages sent so far, newest first.
     */
    public List<ContactMessage> messages() {
        return List.copyOf(messages);
    }

    public void add(ContactMessage message) {
        messages.add(0, message);
    }
}
