+        form.setColspan(message, 2);
+        form.setMaxWidth("40em");
+        add(form);
+
+        messages.addColumn(ContactMessage::name).setHeader("Name").setKey("name").setAutoWidth(true);
+        messages.addColumn(ContactMessage::email).setHeader("Email").setKey("email").setAutoWidth(true);
+        messages.addColumn(ContactMessage::phone).setHeader("Phone").setKey("phone").setAutoWidth(true);
+        messages.addColumn(ContactMessage::message).setHeader("Message").setKey("message").setFlexGrow(1);
+        messages.setAllRowsVisible(true);
+        refreshMessages();
+
+        add(new H2("Sent messages"), messages);
+    }
+
+    private void configureField(TextFieldBase<?, String> field) {
+        // We validate on Send ourselves, so the built-in validation must not
+        // interfere with the error messages we set.
+        field.setManualValidation(true);
+        field.setValueChangeMode(ValueChangeMode.EAGER);
+        field.addValueChangeListener(event -> {
+            if (resetting) {
+                return;
+            }
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+            send.setEnabled(true);
+        });
+    }
+
+    /**
+     * Validates the form and, if everything is in order, sends the message.
+     */
+    private void send() {
+        if (!send.isEnabled()) {
+            return;
+        }
+        clearErrors();
+
+        String nameValue = name.getValue();
+        String emailValue = email.getValue();
+        String phoneValue = phone.getValue();
+        String messageValue = message.getValue();
+
+        boolean valid = true;
+
+        if (nameValue.isBlank()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+
+        if (!emailValue.isBlank() && !EMAIL_PATTERN.matcher(emailValue.trim()).matches()) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isBlank() && phoneValue.isBlank()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (messageValue.isBlank()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            return;
+        }
+
+        MessageStore.current().add(new ContactMessage(nameValue, emailValue, phoneValue, messageValue, Instant.now()));
+        refreshMessages();
+
+        // One notification at a time, rather than a growing stack of them.
+        if (sentNotification != null) {
+            sentNotification.close();
+            sentNotification.removeFromParent();
+        }
+        sentNotification = Notification.show("Message sent");
+        sentNotification.addThemeVariants(NotificationVariant.LUMO_SUCCESS);
+
+        reset();
+    }
+
+    /** Empties the form and disables Send until the next edit. */
+    private void reset() {
+        resetting = true;
+        try {
+            name.clear();
+            email.clear();
+            phone.clear();
+            message.clear();
+            clearErrors();
+        } finally {
+            resetting = false;
+        }
+        send.setEnabled(false);
+    }
+
+    private void markInvalid(TextFieldBase<?, String> field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        List.<TextFieldBase<?, String>> of(name, email, phone, message).forEach(field -> {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        });
+    }
+
+    private void refreshMessages() {
+        messages.setItems(MessageStore.current().messages());
+    }
+
+    /** True if the user has typed something that is not sent yet. */
+    private boolean hasUnsentInput() {
+        return !name.getValue().isEmpty() || !email.getValue().isEmpty() || !phone.getValue().isEmpty()
+                || !message.getValue().isEmpty();
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasUnsentInput()) {
+            return;
+        }
+        ContinueNavigationAction action = event.postpone();
+        if (leaveDialog != null && leaveDialog.isOpened()) {
+            // Already asking; the new attempt just waits for the answer.
+            return;
+        }
+        leaveDialog = createLeaveDialog(action);
+        leaveDialog.open();
+    }
+
+    private Dialog createLeaveDialog(ContinueNavigationAction action) {
+        Dialog dialog = new Dialog();
+        dialog.setHeaderTitle("Discard your message?");
+        dialog.add(new Paragraph("Your message has not been sent yet. If you leave now, it is lost."));
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            closeLeaveDialog();
+            action.cancel();
+        });
+        Button discard = new Button("Discard", event -> {
+            closeLeaveDialog();
+            action.proceed();
+        });
+        discard.addThemeVariants(ButtonVariant.LUMO_ERROR, ButtonVariant.LUMO_PRIMARY);
+
+        dialog.getFooter().add(keepEditing, discard);
+        dialog.setCloseOnEsc(false);
+        dialog.setCloseOnOutsideClick(false);
+        return dialog;
+    }
+
+    private void closeLeaveDialog() {
+        if (leaveDialog != null) {
+            leaveDialog.close();
+            leaveDialog.removeFromParent();
+            leaveDialog = null;
+        }
+    }
+}
