+ */
+@SpringBootTest(webEnvironment = SpringBootTest.WebEnvironment.RANDOM_PORT)
+class ContactViewBrowserTest extends AbstractBasePlaywrightIT {
+
+    @LocalServerPort
+    private int port;
+
+    @Override
+    public String getUrl() {
+        return "http://localhost:" + port;
+    }
+
+    @Override
+    public String getView() {
+        return "/contact";
+    }
+
+    private TextFieldElement name() {
+        return TextFieldElement.getByLabel(page, "Name");
+    }
+
+    private EmailFieldElement email() {
+        return EmailFieldElement.getByLabel(page, "Email");
+    }
+
+    private TextFieldElement phone() {
+        return TextFieldElement.getByLabel(page, "Phone");
+    }
+
+    private TextAreaElement message() {
+        return TextAreaElement.getByLabel(page, "Message");
+    }
+
+    private ButtonElement send() {
+        return ButtonElement.getByText(page, "Send");
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue, String messageValue) {
+        name().setValue(nameValue);
+        email().setValue(emailValue);
+        phone().setValue(phoneValue);
+        message().setValue(messageValue);
+    }
+
+    @Test
+    void formIsRenderedAndSendIsEnabled() {
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+        name().assertValid();
+    }
+
+    @Test
+    void emptyForm_send_showsErrors() {
+        send().click();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+
+        new NotificationElement(page).assertClosed();
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+        send().assertEnabled();
+    }
+
+    @Test
+    void invalidEmail_send_showsEmailError() {
+        fill("Ada", "nope", "", "Hello");
+        send().click();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValid();
+        name().assertValue("Ada");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void tooLongMessage_send_showsMessageError() {
+        fill("Ada", "ada@example.com", "", "x".repeat(501));
+        send().click();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+        assertEquals(0, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void validForm_send_notifiesListsAndDisablesSend() {
+        fill("Ada", "ada@example.com", "", "Hello there");
+        send().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        GridElement grid = GridElement.get(page);
+        assertEquals(1, grid.getTotalRowCount());
+        PlaywrightAssertions.assertThat(grid.findCell(0, 0).orElseThrow().getCellContentLocator()).hasText("Ada");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        name().assertValid();
+        send().assertDisabled();
+
+        name().setValue("Bob");
+        send().assertEnabled();
+    }
+
+    @Test
+    void phoneOnly_isEnoughToSend() {
+        fill("Ada", "", "040 123 4567", "Call me");
+        send().click();
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void enter_sendsTheForm() {
+        fill("Ada", "ada@example.com", "", "Sent with Enter");
+        page.keyboard().press("Enter");
+
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+    }
+
+    @Test
+    void messagesSurviveLeavingTheView() {
+        fill("Ada", "ada@example.com", "", "One");
+        send().click();
+        NotificationElement.getByText(page, "Message sent").assertOpen();
+
+        page.getByText("About").click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        page.getByText("Contact").click();
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+
+        assertEquals(1, GridElement.get(page).getTotalRowCount());
+        PlaywrightAssertions.assertThat(GridElement.get(page).findCell(0, 0).orElseThrow().getCellContentLocator())
+                .hasText("Ada");
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        page.getByText("About").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+        assertFalse(new DialogElement(page).isVisible());
+    }
+
+    @Test
+    void dirtyForm_keepEditing_staysOnTheView() {
+        name().setValue("Ada");
+        page.getByText("About").click();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Keep editing").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("Contact");
+        name().assertValue("Ada");
+    }
+
+    @Test
+    void dirtyForm_discard_navigates() {
+        message().setValue("Half written");
+        page.getByText("About").click();
+
+        new DialogElement(page).assertOpen();
+        ButtonElement.getByText(page, "Discard").click();
+
+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText("About");
+    }
+}
