+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.router.RouterLink;
+
+@SpringBootTest
+class ContactViewTest extends SpringBrowserlessTest {
+
+    @BeforeEach
+    void setUp() {
+        initVaadinEnvironment();
+        navigate(ContactView.class);
+    }
+
+    @AfterEach
+    void tearDown() {
+        cleanVaadinEnvironment();
+    }
+
+    private TextField name() {
+        return $(TextField.class).withLabel("Name").single();
+    }
+
+    private EmailField email() {
+        return $(EmailField.class).withLabel("Email").single();
+    }
+
+    private TextField phone() {
+        return $(TextField.class).withLabel("Phone").single();
+    }
+
+    private TextArea messageField() {
+        return $(TextArea.class).withLabel("Message").single();
+    }
+
+    private Button sendButton() {
+        return $(Button.class).withText("Send").single();
+    }
+
+    private void fill(String nameValue, String emailValue, String phoneValue, String messageValue) {
+        test(name()).setValue(nameValue);
+        test(email()).setValue(emailValue);
+        test(phone()).setValue(phoneValue);
+        test(messageField()).setValue(messageValue);
+    }
+
+    @Test
+    void view_hasHeadingLinkFormAndGrid() {
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("About", $(RouterLink.class).single().getText());
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", messageField().getValue());
+        assertTrue(sendButton().isEnabled(), "Send must be enabled on an untouched form");
+        assertTrue($(Grid.class).exists());
+    }
+
+    @Test
+    void emptyForm_send_marksNameEmailAndMessageInvalid() {
+        test(sendButton()).click();
+
+        assertTrue(name().isInvalid());
+        assertEquals("Name is required", name().getErrorMessage());
+        assertTrue(email().isInvalid());
+        assertEquals("Give an e-mail address or a phone number", email().getErrorMessage());
+        assertTrue(messageField().isInvalid());
+        assertEquals("Message is required", messageField().getErrorMessage());
+
+        assertFalse($(Notification.class).exists(), "Nothing may be sent");
+        assertEquals(0, test($(Grid.class).single()).size());
+        assertTrue(sendButton().isEnabled());
+    }
+
+    @Test
+    void invalidEmail_send_marksEmailInvalid() {
+        fill("Ada", "not-an-email", "", "Hello there");
+        test(sendButton()).click();
+
+        assertTrue(email().isInvalid());
+        assertEquals("Enter a valid e-mail address", email().getErrorMessage());
+        assertFalse(name().isInvalid());
+        assertFalse(messageField().isInvalid());
+        assertEquals("Ada", name().getValue(), "The typed values must stay");
+        assertEquals(0, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void tooLongMessage_send_marksMessageInvalid() {
+        fill("Ada", "ada@example.com", "", "x".repeat(501));
+        test(sendButton()).click();
+
+        assertTrue(messageField().isInvalid());
+        assertEquals("Message must be at most 500 characters", messageField().getErrorMessage());
+        assertEquals(0, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void phoneOnly_isEnoughToSend() {
+        fill("Ada", "", "+358 40 123 4567", "Call me");
+        test(sendButton()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(1, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void emailOnly_isEnoughToSend() {
+        fill("Ada", "ada@example.com", "", "Mail me");
+        test(sendButton()).click();
+
+        assertFalse(email().isInvalid());
+        assertEquals(1, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void validForm_send_notifiesClearsAndDisablesSend() {
+        fill("Ada", "ada@example.com", "", "Hello there");
+        test(sendButton()).click();
+
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+
+        Grid<?> grid = $(Grid.class).single();
+        assertEquals(1, test(grid).size());
+        assertEquals("Ada", test(grid).getCellText(0, 0));
+
+        assertEquals("", name().getValue());
+        assertEquals("", email().getValue());
+        assertEquals("", phone().getValue());
+        assertEquals("", messageField().getValue());
+        assertFalse(name().isInvalid());
+
+        assertFalse(sendButton().isEnabled(), "Send is disabled right after a send");
+        test(name()).setValue("Bob");
+        assertTrue(sendButton().isEnabled(), "Editing enables Send again");
+    }
+
+    @Test
+    void enter_sendsTheForm() {
+        fill("Ada", "ada@example.com", "", "Sent with Enter");
+        fireShortcut(Key.ENTER);
+
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+        assertEquals(1, test($(Grid.class).single()).size());
+    }
+
+    @Test
+    void messages_areListedNewestFirst_andSurviveLeavingTheView() {
+        fill("First", "first@example.com", "", "One");
+        test(sendButton()).click();
+        fill("Second", "second@example.com", "", "Two");
+        test(sendButton()).click();
+
+        navigate(AboutView.class);
+        navigate(ContactView.class);
+
+        Grid<?> grid = $(Grid.class).single();
+        assertEquals(2, test(grid).size());
+        assertEquals("Second", test(grid).getCellText(0, 0));
+        assertEquals("First", test(grid).getCellText(1, 0));
+    }
+
+    @Test
+    void everyFieldEnablesSendAgainAfterASend() {
+        for (int field = 0; field < 4; field++) {
+            fill("Ada", "ada@example.com", "", "Hello");
+            test(sendButton()).click();
+            assertFalse(sendButton().isEnabled());
+
+            switch (field) {
+                case 0 -> test(name()).setValue("x");
+                case 1 -> test(email()).setValue("x");
+                case 2 -> test(phone()).setValue("x");
+                default -> test(messageField()).setValue("x");
+            }
+            assertTrue(sendButton().isEnabled(), "Editing field " + field + " must enable Send");
+            fill("", "", "", "");
+        }
+        // Only the newest notification is around, so a single() query is safe.
+        assertTrue(test($(Notification.class).single()).getText().contains("Message sent"));
+    }
+
+    @Test
+    void afterSending_leavingIsNotInterrupted() {
+        fill("Ada", "ada@example.com", "", "Hello");
+        test(sendButton()).click();
+
+        test($(RouterLink.class).single()).click();
+
+        assertFalse($(Dialog.class).exists());
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void keepEditing_thenLeavingAgain_asksAgain() {
+        test(name()).setValue("Ada");
+        test($(RouterLink.class).single()).click();
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        test($(RouterLink.class).single()).click();
+        assertTrue($(Dialog.class).single().isOpened(), "The question must be asked again");
+        test($(Button.class).withText("Discard").single()).click();
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void emptyForm_leavesWithoutAsking() {
+        test($(RouterLink.class).single()).click();
+
+        assertFalse($(Dialog.class).exists(), "No dialog when there is nothing to lose");
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void dirtyForm_keepEditing_staysOnTheView() {
+        test(name()).setValue("Ada");
+        test($(RouterLink.class).single()).click();
+
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Keep editing").single()).click();
+
+        assertEquals("Contact", $(H1.class).single().getText());
+        assertEquals("Ada", name().getValue());
+    }
+
+    @Test
+    void dirtyForm_discard_navigates() {
+        test(messageField()).setValue("Half written");
+        test($(RouterLink.class).single()).click();
+
+        assertTrue($(Dialog.class).single().isOpened());
+        test($(Button.class).withText("Discard").single()).click();
+
+        assertEquals("About", $(H1.class).single().getText());
+    }
+
+    @Test
+    void dirtyForm_programmaticNavigation_alsoAsks() {
+        test(phone()).setValue("123");
+        com.vaadin.flow.component.UI.getCurrent().navigate(AboutView.class);
+
+        assertTrue($(Dialog.class).single().isOpened());
+        assertEquals("Contact", $(H1.class).single().getText());
+    }
+}
